import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { createServer } from 'node:net';
import { open, readFile, writeFile } from 'node:fs/promises';
import { join, resolve, basename } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

// Use only the synthetic database generated by `npm run bench:mailbox -- --keep`.
const fixture = JSON.parse(await readFile('artifacts/mailbox-optimized.json', 'utf8'));
assert.equal(fixture.syntheticOnly, true);
assert.ok(basename(fixture.dataDir ?? '').startsWith('aplos-scale-'));
assert.equal(fixture.threads, 10000);
const db = new DatabaseSync(join(fixture.dataDir, 'aplos.db'), { readOnly: true });
assert.ok(
  db
    .prepare('SELECT data FROM accounts')
    .all()
    .every(r => JSON.parse(r.data).provider === 'demo'),
);
db.close();
const listener = createServer();
await new Promise(r => listener.listen(0, '127.0.0.1', r));
const port = listener.address().port;
await new Promise(r => listener.close(r));
// This suite drives the legacy engine (`state.get`), no longer the default: pinned until the legacy code goes.
const env = { ...process.env, APLOS_DATA_DIR: fixture.dataDir, APLOS_ENGINE: 'legacy' };
delete env.ELECTRON_RUN_AS_NODE;
const log = await open(join(fixture.dataDir, 'large-desktop.log'), 'a');
const started = performance.now(),
  child = spawn(
    resolve('release/mac-arm64/Aplos Mail.app/Contents/MacOS/Aplos Mail'),
    [
      `--user-data-dir=${join(fixture.dataDir, 'chromium')}`,
      `--remote-debugging-port=${port}`,
      '--remote-debugging-address=127.0.0.1',
    ],
    { env, stdio: ['ignore', log.fd, log.fd] },
  );
await log.close();
let ws;
const until = async (fn, label, timeout = 60000) => {
  const end = Date.now() + timeout;
  let error;
  while (Date.now() < end) {
    try {
      const value = await fn();
      if (value) return value;
    } catch (e) {
      error = e;
    }
    if (child.exitCode !== null) throw new Error('Desktop exited before ' + label);
    await new Promise(r => setTimeout(r, 200));
  }
  throw new Error('Timed out: ' + label + (error ? ' (' + error.message + ')' : ''));
};
try {
  const target = await until(async () => {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    return pages.find(p => p.type === 'page' && p.url.startsWith('file:'));
  }, 'desktop target');
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve, { once: true });
    ws.addEventListener('error', reject, { once: true });
  });
  const pending = new Map();
  let id = 0;
  ws.addEventListener('message', e => {
    const value = JSON.parse(e.data),
      entry = pending.get(value.id);
    if (!entry) return;
    pending.delete(value.id);
    clearTimeout(entry.timer);
    value.error ? entry.reject(new Error(value.error.message)) : entry.resolve(value.result);
  });
  const send = (method, params = {}) =>
    new Promise((resolve, reject) => {
      const key = ++id,
        timer = setTimeout(() => {
          pending.delete(key);
          reject(new Error('Desktop command timed out'));
        }, 60000);
      pending.set(key, { resolve, reject, timer });
      ws.send(JSON.stringify({ id: key, method, params }));
    });
  const evaluate = async expression => {
    const r = await send('Runtime.evaluate', {
      expression,
      awaitPromise: true,
      returnByValue: true,
    });
    if (r.exceptionDetails)
      throw new Error(r.exceptionDetails.exception?.description ?? r.exceptionDetails.text);
    return r.result.value;
  };
  await until(
    () => evaluate('Boolean(document.querySelector("main")&&window.aplos)'),
    'rendered Home',
  );
  const firstPaintMs = Math.round(performance.now() - started);
  await until(
    () =>
      evaluate(
        'document.querySelector("[data-virtual-count=\\\"8000\\\"]")&&document.querySelectorAll(".mail-row").length<100',
      ),
    'windowed Home rows',
  );
  const homeLoadedMs = Math.round(performance.now() - started);
  // Navigation labels are visible button text; keep the query independent of optional aria-labels.
  await evaluate(
    '[...document.querySelectorAll("nav button")].find(b=>b.textContent.trim().startsWith("All mail")).click()',
  );
  await until(
    () =>
      evaluate(
        'document.querySelector("[data-virtual-count=\\\"10000\\\"]")&&document.querySelectorAll(".mail-row").length<100',
      ),
    'windowed All mail',
  );
  await evaluate(
    'document.querySelector(".mail-content").scrollTop=document.querySelector(".mail-content").scrollHeight',
  );
  await until(
    () => evaluate('Boolean(document.querySelector("[data-thread-id=\\\"scale-000000\\\"]"))'),
    'oldest row after scrolling',
  );
  await evaluate('document.querySelector(".mail-content").scrollTop=0');
  await until(
    () => evaluate('Boolean(document.querySelector("[data-thread-id=\\\"scale-009999\\\"]"))'),
    'newest row after scrolling',
  );
  for (let n = 0; n < 40; n++) {
    await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'j', code: 'KeyJ' });
    await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'j', code: 'KeyJ' });
    await evaluate('new Promise(requestAnimationFrame)');
  }
  await until(
    () =>
      evaluate(
        'Boolean(document.querySelector(".mail-row.is-cursor"))&&document.querySelector(".mail-content").scrollTop>0',
      ),
    'keyboard navigation beyond first window',
  );
  await evaluate(
    'document.querySelector(".mail-content").scrollTop=document.querySelector(".mail-content").scrollHeight',
  );
  await until(
    () => evaluate('Boolean(document.querySelector("[data-thread-id=\\\"scale-000000\\\"]"))'),
    'manual scroll after keyboard navigation',
  );
  await evaluate('new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))');
  assert.ok(
    await evaluate('document.querySelector(".mail-content").scrollTop>100000'),
    'Manual scrolling must not snap back to an old keyboard cursor',
  );
  await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'k', code: 'KeyK', modifiers: 4 });
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'k', code: 'KeyK', modifiers: 4 });
  await until(
    () => evaluate(`document.activeElement?.getAttribute('aria-label')==='Search mail query'`),
    'focused search field',
  );
  await send('Input.insertText', { text: 'needlefinch' });
  await until(
    () =>
      evaluate(
        'document.querySelectorAll(".mail-row").length===1&&document.querySelector(".mail-row")?.dataset.threadId==="scale-009999"',
      ),
    'indexed search row',
  );
  const dimensions = await evaluate(
    '({width:innerWidth,height:innerHeight,overflow:document.documentElement.scrollWidth>innerWidth})',
  );
  assert.equal(dimensions.overflow, false);
  const response = await evaluate(
    'window.aplos.invoke("thread.update",{ids:["scale-009999"],patch:{bookmarked:true},compact:true})',
  );
  assert.ok(JSON.stringify(response).length < 200);
  await evaluate('window.aplos.invoke("thread.undo",{compact:true})');
  const report = {
    date: new Date().toISOString(),
    threads: 10000,
    firstPaintMs,
    homeLoadedMs,
    allMailAndSearchVerified: true,
    windowingScrollAndKeyboard: true,
    compactTriageAndUndo: true,
    dimensions,
    syntheticOnly: true,
  };
  await writeFile('artifacts/large-desktop-verification.json', JSON.stringify(report, null, 2));
  console.log(JSON.stringify(report, null, 2));
} finally {
  ws?.close();
  if (child.exitCode === null) {
    const force = setTimeout(() => child.kill('SIGKILL'), 5000);
    force.unref();
    child.kill('SIGTERM');
    await new Promise(resolve => {
      if (child.exitCode !== null || child.signalCode !== null) resolve();
      else child.once('exit', resolve);
    });
    clearTimeout(force);
  }
}
